const StrategistCourse={"id":"ai-business-strategist-course-v1","title":"AI Business Strategist · 四章学习之旅","version":1,"source":"AI_Business_Strategist_Outline.md","chapters":[{"id":"1","title":"AI 基础知识和素养","english":"AI Fundamentals and Literacy","zone":"grove","sections":[{"id":"1.1","title":"描述核心 AI 概念并定义术语","lessons":[{"id":"1.1-lesson-6","title":"人工智能 AI","body":"人工智能是较广的领域，关注让系统执行与智能有关的任务。机器学习是其中一类方法，并非所有自动化都需要机器学习。","example":"清晰、固定的审批条件可直接编写规则，无需为了使用AI而换成模型。","skill":"1.1.2","quote":"区分 AI、机器学习 (ML) 和生成式人工智能 (GenAI)。","source":"用户提供的学习大纲 · 技能 1.1.2","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Artificial intelligence (AI)","body":"A field concerned with systems performing tasks such as perception, reasoning and decision making. Machine learning is one approach within AI.","example":"Compare an intelligent assistant with a simple fixed approval rule.","quote":"Learning objective 1.1.2 · Core AI concepts and terminology","category":"AI fields and learning methods"},"category":"AI领域与学习方法","interaction":"read","references":["https://www.ibm.com/think/topics/artificial-intelligence","https://www.ibm.com/think/topics/machine-learning"]},{"id":"1.1-lesson-7","title":"机器学习 ML","body":"机器学习利用数据学习模式，而不是为所有情况逐一编写规则。数据、目标和验证方式共同影响模型是否适用。","example":"通过历史交易学习异常模式，与人工写定额阈值规则不同。","skill":"1.1.2","quote":"区分 AI、机器学习 (ML) 和生成式人工智能 (GenAI)。","source":"用户提供的学习大纲 · 技能 1.1.2","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Machine learning (ML)","body":"Learning patterns from data rather than explicitly coding a rule for every case; evaluate against a defined task on unseen data.","example":"Learn unusual transaction patterns from historical transactions.","quote":"Learning objective 1.1.2 · Core AI concepts and terminology","category":"AI fields and learning methods"},"category":"AI领域与学习方法","interaction":"assemble","references":["https://www.ibm.com/think/topics/artificial-intelligence","https://www.ibm.com/think/topics/machine-learning"]},{"id":"1.1-lesson-16","title":"深度学习 DL","body":"使用多层神经网络学习数据表示的机器学习方法；它属于机器学习，而不是与AI并列的领域。","example":"识别商品照片中的缺陷。","skill":"1.1.2","quote":"区分 AI、机器学习 (ML) 和生成式人工智能 (GenAI)。","source":"IBM Think · AI / Machine learning；对应大纲 1.1.2","provenance":"根据公开资料整理的教学释义，非官方试题","en":{"title":"Deep learning","body":"Machine learning using multilayer neural networks to learn representations.","example":"Recognize defects in product photos.","quote":"Learning objective 1.1.2 · distinguish AI approaches and capabilities","category":"AI fields and learning methods"},"interaction":"read","references":["https://www.ibm.com/think/topics/artificial-intelligence","https://www.ibm.com/think/topics/machine-learning"],"category":"AI领域与学习方法"},{"id":"1.1-lesson-17","title":"神经网络","body":"由相连的计算节点和可学习权重组成的模型，通过层间计算处理输入。","example":"学习交易特征与欺诈风险的关系。","skill":"1.1.2","quote":"区分 AI、机器学习 (ML) 和生成式人工智能 (GenAI)。","source":"IBM Think · AI / Machine learning；对应大纲 1.1.2","provenance":"根据公开资料整理的教学释义，非官方试题","en":{"title":"Neural network","body":"A model of connected computational nodes with learnable weights.","example":"Learn relationships between transaction features and fraud risk.","quote":"Learning objective 1.1.2 · distinguish AI approaches and capabilities","category":"AI fields and learning methods"},"interaction":"read","references":["https://www.ibm.com/think/topics/artificial-intelligence","https://www.ibm.com/think/topics/machine-learning"],"category":"AI领域与学习方法"},{"id":"1.1-lesson-18","title":"自然语言处理 NLP","body":"使计算机处理和分析人类语言的AI领域，任务包括分类、抽取和翻译。","example":"从工单文字中识别客户诉求。","skill":"1.1.2","quote":"区分 AI、机器学习 (ML) 和生成式人工智能 (GenAI)。","source":"IBM Think · AI / Machine learning；对应大纲 1.1.2","provenance":"根据公开资料整理的教学释义，非官方试题","en":{"title":"Natural language processing (NLP)","body":"AI methods for processing human language, including classification, extraction and translation.","example":"Identify customer requests in support tickets.","quote":"Learning objective 1.1.2 · distinguish AI approaches and capabilities","category":"AI fields and learning methods"},"interaction":"read","references":["https://www.ibm.com/think/topics/artificial-intelligence","https://www.ibm.com/think/topics/machine-learning"],"category":"AI领域与学习方法"},{"id":"1.1-lesson-19","title":"计算机视觉 CV","body":"从图像或视频中提取和解释信息的AI领域。","example":"从产线照片中定位瑕疵。","skill":"1.1.2","quote":"区分 AI、机器学习 (ML) 和生成式人工智能 (GenAI)。","source":"IBM Think · AI / Machine learning；对应大纲 1.1.2","provenance":"根据公开资料整理的教学释义，非官方试题","en":{"title":"Computer vision","body":"AI methods for extracting and interpreting information from images or video.","example":"Locate defects in production-line images.","quote":"Learning objective 1.1.2 · distinguish AI approaches and capabilities","category":"AI fields and learning methods"},"interaction":"read","references":["https://www.ibm.com/think/topics/artificial-intelligence","https://www.ibm.com/think/topics/machine-learning"],"category":"AI领域与学习方法"},{"id":"1.1-lesson-8","title":"生成式人工智能 GenAI","body":"生成式AI能产生文本、图像等内容。语言流畅并不等于事实正确，业务使用需要核对事实、适用性与复核成本。","example":"起草访谈摘要之后，由负责人对照原文检查遗漏和误解。","skill":"1.1.2","quote":"区分 AI、机器学习 (ML) 和生成式人工智能 (GenAI)。","source":"用户提供的学习大纲 · 技能 1.1.2","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Generative AI (GenAI)","body":"AI that generates content such as text or images. Fluent output may still contain unsupported claims.","example":"Check an interview summary against the original recording.","quote":"Learning objective 1.1.2 · Core AI concepts and terminology","category":"AI fields and learning methods"},"category":"AI领域与学习方法","interaction":"read","references":["https://www.ibm.com/think/topics/artificial-intelligence","https://www.ibm.com/think/topics/machine-learning"]},{"id":"1.1-lesson-1","title":"算法 Algorithm","body":"算法是一套可执行的方法或步骤。模型训练也依照算法进行，但算法本身不是训练后得到的模型。","example":"按订单金额排序是一种算法；从订单记录学习需求规律则会得到预测模型。","skill":"1.1.1","quote":"认识和解释业务环境中的基础 AI 概念（例如，算法、模型、训练、推理、预测）。","source":"用户提供的学习大纲 · 技能 1.1.1","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Algorithm","body":"An executable sequence of steps for solving a task; a training algorithm produces a model rather than being that model.","example":"Sorting orders by amount follows an algorithm.","quote":"Learning objective 1.1.1 · Core AI concepts and terminology","category":"Models and operations"},"category":"模型与运行机制","interaction":"read","references":["https://www.ibm.com/think/topics/artificial-intelligence","https://www.ibm.com/think/topics/machine-learning"]},{"id":"1.1-lesson-2","title":"模型 Model","body":"模型是用于将输入映射为输出的表示。在机器学习中，模型的参数通过训练从数据中学习。它的输出需要根据任务目标验证。","example":"将历史销量与日期输入需求模型，得到下一周销量估计。","skill":"1.1.1","quote":"认识和解释业务环境中的基础 AI 概念（例如，算法、模型、训练、推理、预测）。","source":"用户提供的学习大纲 · 技能 1.1.1","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Model","body":"A representation that maps inputs to outputs. In machine learning, training adjusts its parameters using data.","example":"A demand model estimates next week's sales.","quote":"Learning objective 1.1.1 · Core AI concepts and terminology","category":"Models and operations"},"category":"模型与运行机制","interaction":"read","references":["https://www.ibm.com/think/topics/artificial-intelligence","https://www.ibm.com/think/topics/machine-learning"]},{"id":"1.1-lesson-3","title":"训练 Training","body":"训练利用已有样本调整模型参数，使模型学习数据中的模式。训练效果好不代表对新数据一定表现好，需要独立验证。","example":"用过去的订单记录学习需求规律，之后用未参与训练的时段检验。","skill":"1.1.1","quote":"认识和解释业务环境中的基础 AI 概念（例如，算法、模型、训练、推理、预测）。","source":"用户提供的学习大纲 · 技能 1.1.1","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Training","body":"The process of adjusting model parameters using examples to learn patterns. Training performance alone does not establish generalization.","example":"Learn demand patterns from past orders, then evaluate on a separate period.","quote":"Learning objective 1.1.1 · Core AI concepts and terminology","category":"Models and operations"},"category":"模型与运行机制","interaction":"assemble","references":["https://www.ibm.com/think/topics/artificial-intelligence","https://www.ibm.com/think/topics/machine-learning"]},{"id":"1.1-lesson-4","title":"推理 Inference","body":"推理是使用已训练的模型处理新输入。训练改变参数；推理通常使用已有参数产生预测或生成内容。","example":"上线的客服模型为一张新工单起草回复，属于推理。","skill":"1.1.1","quote":"认识和解释业务环境中的基础 AI 概念（例如，算法、模型、训练、推理、预测）。","source":"用户提供的学习大纲 · 技能 1.1.1","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Inference","body":"Using an already trained model on an input to produce an output, normally without updating its parameters.","example":"Drafting a reply to a new support ticket is inference.","quote":"Learning objective 1.1.1 · Core AI concepts and terminology","category":"Models and operations"},"category":"模型与运行机制","interaction":"read","references":["https://www.ibm.com/think/topics/artificial-intelligence","https://www.ibm.com/think/topics/machine-learning"]},{"id":"1.1-lesson-5","title":"预测 Prediction","body":"预测是利用输入和已学习的模式估计未知结果。业务评价既要看误差，也要看错误会造成的后果。","example":"需求高估可能造成库存积压；低估则可能造成缺货。","skill":"1.1.1","quote":"认识和解释业务环境中的基础 AI 概念（例如，算法、模型、训练、推理、预测）。","source":"用户提供的学习大纲 · 技能 1.1.1","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Prediction","body":"An estimate of an unknown outcome from input information and learned patterns; assess both error and its business consequences.","example":"Overestimating demand can increase excess inventory.","quote":"Learning objective 1.1.1 · Core AI concepts and terminology","category":"Models and operations"},"category":"模型与运行机制","interaction":"read","references":["https://www.ibm.com/think/topics/artificial-intelligence","https://www.ibm.com/think/topics/machine-learning"]},{"id":"1.1-lesson-20","title":"监督学习","body":"使用带有目标标签的样本学习输入到目标的映射，可用于分类和回归。","example":"利用已标记是否欺诈的交易训练分类器。","skill":"1.1.2","quote":"区分 AI、机器学习 (ML) 和生成式人工智能 (GenAI)。","source":"IBM Think · AI / Machine learning；对应大纲 1.1.2","provenance":"根据公开资料整理的教学释义，非官方试题","en":{"title":"Supervised learning","body":"Learning an input-to-target mapping from labeled examples, for classification or regression.","example":"Train a classifier on transactions labeled as fraudulent or legitimate.","quote":"Learning objective 1.1.2 · distinguish AI approaches and capabilities","category":"AI fields and learning methods"},"interaction":"read","references":["https://www.ibm.com/think/topics/artificial-intelligence","https://www.ibm.com/think/topics/machine-learning"],"category":"AI领域与学习方法"},{"id":"1.1-lesson-21","title":"无监督学习","body":"从没有目标标签的数据中寻找结构或模式，例如将相似对象聚类。","example":"按购买特征形成客户分群。","skill":"1.1.2","quote":"区分 AI、机器学习 (ML) 和生成式人工智能 (GenAI)。","source":"IBM Think · AI / Machine learning；对应大纲 1.1.2","provenance":"根据公开资料整理的教学释义，非官方试题","en":{"title":"Unsupervised learning","body":"Finding structure or patterns in data without target labels, such as clustering similar cases.","example":"Group customers by purchasing patterns.","quote":"Learning objective 1.1.2 · distinguish AI approaches and capabilities","category":"AI fields and learning methods"},"interaction":"read","references":["https://www.ibm.com/think/topics/artificial-intelligence","https://www.ibm.com/think/topics/machine-learning"],"category":"AI领域与学习方法"},{"id":"1.1-lesson-22","title":"强化学习","body":"智能体通过与环境交互和奖励反馈学习行动策略，关注长期累计回报。","example":"在模拟环境中学习库存补货策略。","skill":"1.1.2","quote":"区分 AI、机器学习 (ML) 和生成式人工智能 (GenAI)。","source":"IBM Think · AI / Machine learning；对应大纲 1.1.2","provenance":"根据公开资料整理的教学释义，非官方试题","en":{"title":"Reinforcement learning","body":"Learning an action policy through interaction and reward feedback to improve cumulative return.","example":"Learn a replenishment policy in a simulated environment.","quote":"Learning objective 1.1.2 · distinguish AI approaches and capabilities","category":"AI fields and learning methods"},"interaction":"read","references":["https://www.ibm.com/think/topics/artificial-intelligence","https://www.ibm.com/think/topics/machine-learning"],"category":"AI领域与学习方法"},{"id":"1.1-lesson-9","title":"结构化数据","body":"结构化数据有相对明确的字段或模式，便于按统一口径查询、统计和校验。结构清晰不等于内容必然准确。","example":"订单表中的日期、商品编号、数量，是明确的字段。","skill":"1.1.3","quote":"区分结构化数据和非结构化数据，并解释 AI 的数据类型相关性。","source":"用户提供的学习大纲 · 技能 1.1.3","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Structured data","body":"Data organized with a defined schema or fields. A clear structure does not guarantee accurate values.","example":"An order table has date, product and quantity fields.","quote":"Learning objective 1.1.3 · Core AI concepts and terminology","category":"Data formats"},"category":"数据形态","interaction":"read","references":[]},{"id":"1.1-lesson-10","title":"非结构化数据","body":"非结构化数据通常不像关系表那样具有固定字段结构，常见形式有正文、图片和录音。使用前可能需要提取与组织信息。","example":"客户录音可先转写，再提取诉求；不能把转写过程当成事实核验。","skill":"1.1.3","quote":"区分结构化数据和非结构化数据，并解释 AI 的数据类型相关性。","source":"用户提供的学习大纲 · 技能 1.1.3","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Unstructured data","body":"Information without the fixed field structure of a conventional table, such as prose, images and audio.","example":"Transcribe a customer call before extracting the request.","quote":"Learning objective 1.1.3 · Core AI concepts and terminology","category":"Data formats"},"category":"数据形态","interaction":"read","references":[]},{"id":"1.1-lesson-11","title":"数据质量","body":"数据质量要结合用途检查准确性、完整性、一致性、时效性及相关性。更大的模型无法自动补救所有数据缺陷。","example":"销售数据存在重复订单，先调查重复来源再比较模型方案。","skill":"1.1.4","quote":"描述为什么数据质量对 AI 的输出结果有很大的影响。","source":"用户提供的学习大纲 · 技能 1.1.4","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Data quality","body":"The fitness of data for its intended use, including accuracy, completeness, consistency, timeliness and relevance.","example":"Investigate duplicate orders before comparing demand models.","quote":"Learning objective 1.1.4 · Core AI concepts and terminology","category":"Data quality"},"category":"数据质量","interaction":"assemble","references":[]},{"id":"1.1-lesson-12","title":"历史数据与泛化","body":"历史数据反映过去的条件。要用独立数据检验模型能否处理未见情况，并留意未来环境与历史数据是否不同。","example":"用过去节日销量训练的模型，遇到新的促销方式时仍需监测。","skill":"1.1.5","quote":"解释与使用历史数据训练 AI 模型相关的概念。","source":"用户提供的学习大纲 · 技能 1.1.5","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Generalization and historical data","body":"Generalization is useful performance on unseen cases; historical conditions may differ from deployment conditions.","example":"Monitor a sales model after a new promotion changes demand.","quote":"Learning objective 1.1.5 · Core AI concepts and terminology","category":"Evaluation and generalization"},"category":"验证与泛化","interaction":"read","references":["https://www.ibm.com/think/topics/artificial-intelligence","https://www.ibm.com/think/topics/machine-learning"]},{"id":"1.1-lesson-13","title":"训练集与验证","body":"训练数据用于学习，独立验证或测试用于检验未见样本的表现。把测试答案带入训练会让结果显得过于乐观。","example":"不要将上线测试工单的标准答案直接放进待评估模型的输入。","skill":"1.1.5","quote":"解释与使用历史数据训练 AI 模型相关的概念。","source":"用户提供的学习大纲 · 技能 1.1.5","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Training, validation and test sets","body":"Training fits parameters, validation supports development choices, and a held-out test estimates final performance. Leakage makes evaluation misleading.","example":"Keep test-ticket answers out of training and evaluation inputs.","quote":"Learning objective 1.1.5 · Core AI concepts and terminology","category":"Evaluation and generalization"},"category":"验证与泛化","interaction":"read","references":["https://www.ibm.com/think/topics/artificial-intelligence","https://www.ibm.com/think/topics/machine-learning"]},{"id":"1.1-lesson-14","title":"AI框架与统一词汇","body":"团队应先统一算法、模型、训练和推理等词的含义，再讨论方案。标准或框架可以帮助组织概念，但不能当作准确率保证。","example":"业务说的“模型上线”与技术说的“模型训练完成”不是同一件事。","skill":"1.1.6","quote":"确保了解全球框架和统一的 AI 词汇表（例如，ISO/IEC 23053、ISO/IEC 42001）。","source":"用户提供的学习大纲 · 技能 1.1.6","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Shared AI vocabulary","body":"Consistent definitions help teams distinguish models, algorithms, training and inference when making decisions.","example":"Training completed does not mean deployment is operationally ready.","quote":"Learning objective 1.1.6 · Core AI concepts and terminology","category":"Vocabulary and standards"},"category":"词汇与标准","interaction":"read","references":[]},{"id":"1.1-lesson-15","title":"ISO框架意识","body":"按本课程大纲，需了解ISO/IEC 23053与ISO/IEC 42001等框架。前者关注使用机器学习的AI系统框架，后者关注组织AI管理体系；具体要求应查正式标准。","example":"讨论组织责任和管理流程时，不把管理体系标准解释为模型零错误认证。","skill":"1.1.6","quote":"确保了解全球框架和统一的 AI 词汇表（例如，ISO/IEC 23053、ISO/IEC 42001）。","source":"用户提供的学习大纲 · 技能 1.1.6","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"AI standards and management frameworks","body":"ISO/IEC 23053 addresses frameworks for AI systems using ML; ISO/IEC 42001 addresses an organizational AI management system. Neither guarantees zero model errors.","example":"Separate technical system design from management responsibilities.","quote":"Learning objective 1.1.6 · Core AI concepts and terminology","category":"Vocabulary and standards"},"category":"词汇与标准","interaction":"assemble","references":["https://www.iso.org/standard/42001","https://webstore.iec.ch/en/publication/77056"]}],"english":"Core AI concepts and terminology","matchRequired":true},{"id":"1.2","title":"确定并选择适当的 AI 解决方案类型","lessons":[{"id":"1.2-lesson-1","title":"规则还是AI","body":"条件明确且稳定时，优先考虑确定性规则。模式复杂、规则难穷举时再评估AI；比较价值、错误后果和维护成本。","example":"报销超过明确金额需审批，可以先采用固定规则。","skill":"1.2.1","quote":"确定何时使用基于规则的自动化以及何时使用 AI 解决方案。","source":"用户提供的学习大纲 · 技能 1.2.1","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Rules or AI","body":"Prefer explicit rules for stable, well-defined conditions; assess AI for complex patterns, accounting for value, errors and maintenance.","example":"A fixed expense threshold can use a deterministic rule.","quote":"Learning objective 1.2.1 · Choosing and operating AI solutions","category":"Choosing and operating AI solutions"},"category":"确定并选择适当的 AI 解决方案类型","interaction":"read","references":[]},{"id":"1.2-lesson-2","title":"AI代理与工具","body":"代理围绕目标协调步骤和工具，可能具有一定自主性。代理的行动权限、失败处理和监督方式需要单独设计。","example":"能调用退款工具的助手，需要退款额度、日志和人工升级边界。","skill":"1.2.2","quote":"将 AI 代理与其他 AI 解决方案区分开来，确定 AI 代理的核心功能（例如，自主性、工具使用、代理间通信和编排策略）。","source":"用户提供的学习大纲 · 技能 1.2.2","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"AI agents and tools","body":"An agent coordinates actions and tools toward a goal with some autonomy; permissions, supervision and failure handling require explicit design.","example":"A refund agent needs an amount limit and escalation path.","quote":"Learning objective 1.2.2 · Choosing and operating AI solutions","category":"Choosing and operating AI solutions"},"category":"确定并选择适当的 AI 解决方案类型","interaction":"read","references":[]},{"id":"1.2-lesson-3","title":"代理协作与编排","body":"多个代理的角色分工、信息交换和执行顺序属于编排问题。角色越多不自动代表效果越好，要检查任务完成与交接质量。","example":"检索代理交给起草代理的资料仍需保留来源和访问范围。","skill":"1.2.2","quote":"将 AI 代理与其他 AI 解决方案区分开来，确定 AI 代理的核心功能（例如，自主性、工具使用、代理间通信和编排策略）。","source":"用户提供的学习大纲 · 技能 1.2.2","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Multi-agent orchestration","body":"Coordinating roles, information exchange and execution among agents. More agents do not automatically improve outcomes.","example":"Preserve sources and permissions when handing retrieved evidence to a drafting agent.","quote":"Learning objective 1.2.2 · Choosing and operating AI solutions","category":"Choosing and operating AI solutions"},"category":"确定并选择适当的 AI 解决方案类型","interaction":"assemble","references":[]},{"id":"1.2-lesson-4","title":"模型漂移与持续监测","body":"输入分布或业务关系变化可能使模型表现变差。部署后持续观察质量、成本和反馈，发现变化后调查原因并纠正。","example":"客户群变化后投诉分类变差，应调查新文本与原有训练样本的差别。","skill":"1.2.3","quote":"描述为什么需要持续监控和更新 AI 解决方案，以便检测和修复模型漂移和性能变化。","source":"用户提供的学习大纲 · 技能 1.2.3","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Drift and ongoing monitoring","body":"Changes in inputs or relationships can reduce model performance; monitor quality, costs and feedback after deployment.","example":"Investigate new customer language when complaint classification degrades.","quote":"Learning objective 1.2.3 · Choosing and operating AI solutions","category":"Choosing and operating AI solutions"},"category":"确定并选择适当的 AI 解决方案类型","interaction":"read","references":[]},{"id":"1.2-lesson-5","title":"工具分类与影子AI","body":"明确哪些工具已批准、受限、被阻止或仍在评估，说明数据使用边界并提供合适替代方案，有助于减少未经批准的使用。","example":"员工需要处理敏感文档时，应知道可用工具和求助渠道。","skill":"1.2.4","quote":"建立透明的 AI 工具分类体系（例如，已批准、已阻止、正在评估），减少影子 AI 风险。","source":"用户提供的学习大纲 · 技能 1.2.4","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Tool policies and shadow AI","body":"Define approved, restricted, blocked and evaluated tools, their data boundaries and supported alternatives.","example":"Tell employees which approved service can handle sensitive documents.","quote":"Learning objective 1.2.4 · Choosing and operating AI solutions","category":"Choosing and operating AI solutions"},"category":"确定并选择适当的 AI 解决方案类型","interaction":"read","references":[]}],"english":"Choosing and operating AI solutions","matchRequired":true},{"id":"1.3","title":"应用生成式人工智能概念和技术","lessons":[{"id":"1.3-lesson-1","title":"提示工程","body":"提示应说明目标、必要背景、约束和期望输出。用代表性任务测试提示，避免只看一条漂亮回答。","example":"要求依据提供的访谈生成三点摘要，并为每点标出对应原文。","skill":"1.3.1","quote":"应用基本的提示工程原理来实现所需的 AI 输出。","source":"用户提供的学习大纲 · 技能 1.3.1","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Prompt engineering","body":"Design instructions with a goal, relevant context, constraints and output expectations; evaluate on representative tasks.","example":"Ask for three summary points with supporting passages.","quote":"Learning objective 1.3.1 · Generative AI techniques","category":"Generative AI techniques"},"category":"应用生成式人工智能概念和技术","interaction":"read","references":[]},{"id":"1.3-lesson-2","title":"词元与上下文窗口","body":"模型一次请求可处理的上下文有上限，输入与输出预算需要规划。资料过多时应筛选相关片段，而不是假设全部文件都会被有效使用。","example":"先按章节切分教材，再提供与当前问题直接相关的段落。","skill":"1.3.2","quote":"确定词元限制或上下文窗口限制何时影响生成式人工智能系统性能。","source":"用户提供的学习大纲 · 技能 1.3.2","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Tokens and context windows","body":"Tokens are units processed by a model; the context window limits information available in a request, including input and output budgets.","example":"Select relevant textbook passages instead of assuming every file fits.","quote":"Learning objective 1.3.2 · Generative AI techniques","category":"Generative AI techniques"},"category":"应用生成式人工智能概念和技术","interaction":"read","references":[]},{"id":"1.3-lesson-3","title":"检索增强生成 RAG","body":"RAG先检索相关且获授权的资料，再把资料提供给生成过程。它改善可用信息条件，但不保证检索和回答一定正确。","example":"制度频繁更新时，核对检索资料的版本、权限和回答引用。","skill":"1.3.3","quote":"认识模型自适应技术（例如，检索增强生成 [RAG]、微调）如何改善 AI 对特定业务需求的响应。","source":"用户提供的学习大纲 · 技能 1.3.3","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Retrieval-augmented generation (RAG)","body":"Retrieve relevant authorized information and provide it as context for generation. Retrieval and answers still require verification.","example":"Check a policy assistant's source version and access permissions.","quote":"Learning objective 1.3.3 · Generative AI techniques","category":"Generative AI techniques"},"category":"应用生成式人工智能概念和技术","interaction":"assemble","references":[]},{"id":"1.3-lesson-4","title":"微调 Fine-tuning","body":"微调利用训练样本调整模型行为或任务适应性。它与在请求中加入新资料不同，也不能替代对不断变化事实的维护。","example":"统一输出风格与补充最新制度属于不同需求，先辨别问题再选技术。","skill":"1.3.3","quote":"认识模型自适应技术（例如，检索增强生成 [RAG]、微调）如何改善 AI 对特定业务需求的响应。","source":"用户提供的学习大纲 · 技能 1.3.3","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Fine-tuning","body":"Further training that adjusts model parameters for a task or behavior, distinct from adding information to a prompt.","example":"Separate a style adaptation need from a need for current policy facts.","quote":"Learning objective 1.3.3 · Generative AI techniques","category":"Generative AI techniques"},"category":"应用生成式人工智能概念和技术","interaction":"read","references":[]}],"english":"Generative AI techniques","matchRequired":true}]},{"id":"2","title":"AI 战略和商业价值创造","english":"AI Strategy and Business Value Creation","zone":"harbor","sections":[{"id":"2.1","title":"制定符合业务目标的 AI 战略","lessons":[{"id":"2.1-lesson-1","title":"从业务问题到用例","body":"先明确谁在什么流程中遇到什么问题，再把AI能力映射到可观察的业务结果。技术选择要服务目标。","example":"将“做一个AI助手”改为“减少客服查找获授权制度的时间，同时保持答复质量”。","skill":"2.1.1","quote":"确定跨业务职能（例如，客户运营、销售和营销、研发、软件开发）的高影响力 AI 使用案例，并将 AI 功能与特定业务成果对应起来。","source":"用户提供的学习大纲 · 技能 2.1.1","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"From business problems to use cases","body":"Specify the affected people, workflow and observable problem before mapping AI capabilities to desired outcomes.","example":"Reduce time spent finding authorized policies while preserving response quality.","quote":"Learning objective 2.1.1 · Strategy and use-case decisions","category":"Strategy and use-case decisions"},"category":"制定符合业务目标的 AI 战略","interaction":"read","references":[]},{"id":"2.1-lesson-2","title":"自建、购买或合作","body":"比较预算、交付时间、内部能力、供应商条件和合规需求。也要考虑集成、维护、迁移与持续运营成本。","example":"现有团队缺少运维能力时，不能只比较模型购买价格。","skill":"2.1.2","quote":"评估 AI 实施的自建、购买或合作开发决策（考虑的因素包括预算、时间表、能力、供应商提议和监管合规要求）。","source":"用户提供的学习大纲 · 技能 2.1.2","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Build, buy or partner","body":"Compare internal capabilities, delivery time, budget, supplier constraints, integration, maintenance and exit costs.","example":"A team without operations capability must consider support requirements.","quote":"Learning objective 2.1.2 · Strategy and use-case decisions","category":"Strategy and use-case decisions"},"category":"制定符合业务目标的 AI 战略","interaction":"read","references":[]},{"id":"2.1-lesson-3","title":"项目优先级","body":"综合商业价值、可行性、可持续性及战略契合度，决定扩展、暂停还是终止。先定义检验假设和停止条件。","example":"高潜在收益但数据不可用的项目，应先验证准备条件。","skill":"2.1.3","quote":"根据商业价值、可行性、可持续性和战略契合度，来确定 AI 计划的优先级（决定是扩展、暂停还是终止计划）。","source":"用户提供的学习大纲 · 技能 2.1.3","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Project prioritization","body":"Rank initiatives by value, feasibility, sustainability and strategic fit; define evidence and conditions for stopping or scaling.","example":"Validate data availability before committing to a high-return proposal.","quote":"Learning objective 2.1.3 · Strategy and use-case decisions","category":"Strategy and use-case decisions"},"category":"制定符合业务目标的 AI 战略","interaction":"assemble","references":[]},{"id":"2.1-lesson-4","title":"什么时候不该用AI","body":"当明确规则或流程改进已能解决问题，或错误风险与收益不相称时，AI可能不是合适选择。先比较可行替代方案。","example":"资料命名混乱导致找不到文件，可以先改进归档与检索。","skill":"2.1.4","quote":"确定在什么情况下 AI 并非解决业务问题的合适解决方案。","source":"用户提供的学习大纲 · 技能 2.1.4","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"When not to use AI","body":"Choose alternatives when rules or process improvements solve the problem more reliably or errors outweigh benefits.","example":"Improve document organization before commissioning a new AI system.","quote":"Learning objective 2.1.4 · Strategy and use-case decisions","category":"Strategy and use-case decisions"},"category":"制定符合业务目标的 AI 战略","interaction":"read","references":[]},{"id":"2.1-lesson-5","title":"迁移与业务连续性","body":"切换流程或平台要检查数据准备、性能、权限、成本以及回退路径，避免演示成功后直接替换关键流程。","example":"先小范围试用新客服系统，保留可用的人工处理方式。","skill":"2.1.5","quote":"针对准备将业务流程转向基于 AI 的解决方案或在不同 AI 平台之间进行迁移的情况，评估关键注意事项（例如，业务连续性、成本影响、数据准备情况、性能影响）。","source":"用户提供的学习大纲 · 技能 2.1.5","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Migration and business continuity","body":"Plan dependencies, staged migration, fallback procedures and ownership to maintain essential operations.","example":"Keep an approved fallback route during a system transition.","quote":"Learning objective 2.1.5 · Strategy and use-case decisions","category":"Strategy and use-case decisions"},"category":"制定符合业务目标的 AI 战略","interaction":"assemble","references":[]}],"english":"Strategy and use-case decisions","matchRequired":true},{"id":"2.2","title":"衡量和演示 AI 商业价值","lessons":[{"id":"2.2-lesson-1","title":"有形与无形收益","body":"KPI应对应业务目标。有形收益如实际节支或收入，无形收益如满意度；两者需要清楚的测量方式，不能随意互相折算。","example":"同时记录客服处理时间与答复质量，避免只优化生成速度。","skill":"2.2.1","quote":"为 AI 计划定义关键绩效指标 (KPI)，包括有形收益（例如，降低成本、增加收入）和无形收益（例如，客户满意度、员工生产力）。","source":"用户提供的学习大纲 · 技能 2.2.1","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Tangible and intangible benefits","body":"Distinguish measurable financial or operational benefits from less direct effects such as trust or experience; state measurement assumptions.","example":"Measure time saved and assess customer experience separately.","quote":"Learning objective 2.2.1 · Measuring business value","category":"Measuring business value"},"category":"衡量和演示 AI 商业价值","interaction":"read","references":[]},{"id":"2.2-lesson-2","title":"业务基线","body":"实施前记录可比较的原流程表现，包括时间、成本和质量。上线后保持口径一致，才能合理讨论改善。","example":"原流程60分钟，AI生成10分钟且复核15分钟，净节省是35分钟。","skill":"2.2.2","quote":"在实施 AI 解决方案之前先建立基准指标，以便准确衡量采用 AI 带来的成果。","source":"用户提供的学习大纲 · 技能 2.2.2","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Business baseline","body":"A measured reference for the existing process, needed for a meaningful before-and-after comparison.","example":"Record current handling time and error rates before a pilot.","quote":"Learning objective 2.2.2 · Measuring business value","category":"Measuring business value"},"category":"衡量和演示 AI 商业价值","interaction":"read","references":[]},{"id":"2.2-lesson-3","title":"收益与ROI","body":"简单ROI为（同期间收益减成本）除以成本。完整成本应覆盖部署、调用、培训、维护和复核，避免重复计算同一份收益。","example":"释放工时不自动等于现金节支，也不能同时无依据地再记作新增收入。","skill":"2.2.3","quote":"通过使用全面的框架来计算 AI 的投资回报 (ROI)（例如节省时间、降低成本、增加收入、提升生产力）。","source":"用户提供的学习大纲 · 技能 2.2.3","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Benefits and ROI","body":"ROI compares net benefit with investment over a defined period; include ongoing costs and explicit assumptions.","example":"If benefits are 150 and costs are 100, ROI is (150-100)/100 = 50%.","quote":"Learning objective 2.2.3 · Measuring business value","category":"Measuring business value"},"category":"衡量和演示 AI 商业价值","interaction":"assemble","references":[]},{"id":"2.2-lesson-4","title":"先导性指标","body":"先导指标用于较早观察成功条件，结果指标用于观察已实现的成果。先导信号有价值，但不构成最终成功保证。","example":"合适的活跃使用与流程采用可作为信号，仍需观察实际质量和业务价值。","skill":"2.2.4","quote":"确定用于预测 AI 项目成功与否的先导性指标。","source":"用户提供的学习大纲 · 技能 2.2.4","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Leading indicators","body":"Early measures signal likely progress but are not proof of realized business value.","example":"Usage can inform adoption monitoring without proving improved profit.","quote":"Learning objective 2.2.4 · Measuring business value","category":"Measuring business value"},"category":"衡量和演示 AI 商业价值","interaction":"read","references":[]},{"id":"2.2-lesson-5","title":"成本规划与优化","body":"明确初期和持续成本、用量假设与预算边界；观察实际调用和复核开销，在质量约束下优化方案。","example":"比较方案时把培训、集成、监测和人工复核一起计入。","skill":"2.2.5","quote":"为 AI 实施建立基本的成本因素控制措施，包括成本规划和优化策略。","source":"用户提供的学习大纲 · 技能 2.2.5","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Cost planning and optimization","body":"Account for development, data, integration, inference, monitoring, support and maintenance over the lifecycle.","example":"Include review effort and ongoing operating costs in the budget.","quote":"Learning objective 2.2.5 · Measuring business value","category":"Measuring business value"},"category":"衡量和演示 AI 商业价值","interaction":"read","references":[]}],"english":"Measuring business value","matchRequired":true},{"id":"2.3","title":"确立 AI 所能带来的竞争优势","lessons":[{"id":"2.3-lesson-1","title":"竞争格局","body":"比较客户需求、竞争者能力和自己的独特条件，找到AI可改善的业务环节，而不是仅追随流行工具。","example":"同样购买一个模型，并不意味着获得与竞争者不同的能力。","skill":"2.3.1","quote":"评估竞争格局并确定采用 AI 的优势。","source":"用户提供的学习大纲 · 技能 2.3.1","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Competitive landscape","body":"Assess industry conditions, competitors and customer expectations before choosing an AI investment.","example":"Identify a customer need rather than copying a competitor's demo.","quote":"Learning objective 2.3.1 · Competition and business models","category":"Competition and business models"},"category":"确立 AI 所能带来的竞争优势","interaction":"read","references":[]},{"id":"2.3-lesson-2","title":"业务模式转型","body":"AI可能改变产品、服务、交付或价值获取方式。评估客户价值与运营要求，而不是只给原流程加一个聊天窗口。","example":"将一次性报告服务改成持续辅助决策，需要新的数据维护和服务流程。","skill":"2.3.2","quote":"确定使用 AI 解决方案实现业务模式转型的机会。","source":"用户提供的学习大纲 · 技能 2.3.2","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Business model transformation","body":"AI can change how value is created, delivered and captured, beyond automating an existing task.","example":"Consider whether a personalized service changes the revenue model.","quote":"Learning objective 2.3.2 · Competition and business models","category":"Competition and business models"},"category":"确立 AI 所能带来的竞争优势","interaction":"read","references":[]},{"id":"2.3-lesson-3","title":"可持续优势","body":"可持续优势往往来自相关数据、流程、组织能力和反馈的组合。单一工具上线不保证长期优势。","example":"把客户反馈持续转成流程改进，比只记录软件安装数更有意义。","skill":"2.3.3","quote":"描述 AI 如何推动实现可持续的竞争优势和运营改进。","source":"用户提供的学习大纲 · 技能 2.3.3","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Sustainable advantage","body":"Durable advantage depends on capabilities, workflows, data and learning that competitors cannot easily reproduce.","example":"A widely available model alone is unlikely to be a lasting differentiator.","quote":"Learning objective 2.3.3 · Competition and business models","category":"Competition and business models"},"category":"确立 AI 所能带来的竞争优势","interaction":"assemble","references":[]},{"id":"2.3-lesson-4","title":"投资与成熟度","body":"投资规模应结合行业变化、竞争压力、组织准备度及风险承受能力。需要验证条件与分阶段投入。","example":"在数据基础不稳时，先投入治理与小范围验证，而非立即全企业扩展。","skill":"2.3.4","quote":"根据行业成熟度和竞争动态，确定合适的 AI 投资水平。","source":"用户提供的学习大纲 · 技能 2.3.4","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Investment and maturity","body":"Match investment to organizational readiness, competitive conditions and risk tolerance; stage commitments around evidence.","example":"Improve data governance before expanding an unproven enterprise rollout.","quote":"Learning objective 2.3.4 · Competition and business models","category":"Competition and business models"},"category":"确立 AI 所能带来的竞争优势","interaction":"read","references":[]}],"english":"Competition and business models","matchRequired":true}]},{"id":"3","title":"AI 治理与负责任的领导力","english":"AI Governance and Responsible AI Leadership","zone":"town","sections":[{"id":"3.1","title":"在制订业务决策时应用负责任的 AI 原则","lessons":[{"id":"3.1-lesson-1","title":"负责任的AI原则","body":"公平性、可说明性、隐私、安全、透明度和稳健性需要进入实际决策与控制，而不仅是口号。不同任务需要相应评估。","example":"除平均准确率外，也检查不同群体的错误和影响。","skill":"3.1.1","quote":"在业务场景中应用负责任的 AI 原则和维度（例如，公平性、可说明性、隐私、安全、透明度、稳健性）。","source":"用户提供的学习大纲 · 技能 3.1.1","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Responsible AI principles","body":"Fairness, explainability, privacy, security, transparency and robustness should become concrete evaluation and control practices.","example":"Examine errors across relevant groups as well as overall accuracy.","quote":"Learning objective 3.1.1 · Responsible AI decisions","category":"Responsible AI decisions"},"category":"在制订业务决策时应用负责任的 AI 原则","interaction":"read","references":[]},{"id":"3.1-lesson-2","title":"目标冲突与取舍","body":"效率、成本与责任要求可能冲突。把影响、约束和决策责任公开，选择与风险相称的措施并记录理由。","example":"更快地自动发送高影响决定，不一定比保留人工复核更合适。","skill":"3.1.2","quote":"当业务目标与负责任的 AI 原则冲突时，进行权衡取舍。","source":"用户提供的学习大纲 · 技能 3.1.2","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Competing objectives and trade-offs","body":"Document conflicts between business objectives and responsibility requirements, affected parties, decision owners and proportionate controls.","example":"Consider human review before automating a high-impact decision.","quote":"Learning objective 3.1.2 · Responsible AI decisions","category":"Responsible AI decisions"},"category":"在制订业务决策时应用负责任的 AI 原则","interaction":"read","references":[]},{"id":"3.1-lesson-3","title":"从设计时纳入治理","body":"在项目规划和设计阶段确定数据用途、责任、验证与监督，避免上线后才补救关键问题。","example":"选数据之前就讨论访问权限和允许用途。","skill":"3.1.3","quote":"确定在 AI 项目规划中应何时融入负责任的 AI 实践，确保在设计时便纳入了监管措施。","source":"用户提供的学习大纲 · 技能 3.1.3","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Governance by design","body":"Define intended use, data responsibilities, evaluation and oversight during planning and design, before deployment.","example":"Review permitted data use before selecting a dataset.","quote":"Learning objective 3.1.3 · Responsible AI decisions","category":"Responsible AI decisions"},"category":"在制订业务决策时应用负责任的 AI 原则","interaction":"assemble","references":[]},{"id":"3.1-lesson-4","title":"人工监督与升级","body":"明确何时人工检查、何时停止自动行动、何时上报，以及由谁接手。模型的自信措辞不能替代正式授权。","example":"出现缺乏来源的重要结论时，交给有责任的人员核验。","skill":"3.1.4","quote":"识别 AI 系统需要人工监督的情况，并确定适当的保障措施（例如，幻觉检测、防护机制、进行上报的标准）。","source":"用户提供的学习大纲 · 技能 3.1.4","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Human oversight and escalation","body":"Specify when people review, stop or take over an AI process and who has decision authority.","example":"Escalate an important unsupported claim for authorized verification.","quote":"Learning objective 3.1.4 · Responsible AI decisions","category":"Responsible AI decisions"},"category":"在制订业务决策时应用负责任的 AI 原则","interaction":"read","references":[]}],"english":"Responsible AI decisions","matchRequired":true},{"id":"3.2","title":"建立 AI 监管结构并确保监管合规","lessons":[{"id":"3.2-lesson-1","title":"跨职能治理与问责","body":"业务、技术、数据、法务及合规等角色共同参与，并明确谁负责哪些决策。多人参与不代表责任可以模糊。","example":"明确谁批准用途、谁维护资料、谁处理异常。","skill":"3.2.1","quote":"建立具有合理跨职能部门代表性和明确问责机制的 AI 监管结构。","source":"用户提供的学习大纲 · 技能 3.2.1","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Cross-functional governance and accountability","body":"Include business, technical, data and relevant oversight roles with explicit decision responsibilities.","example":"Assign owners for use approval, source maintenance and incident handling.","quote":"Learning objective 3.2.1 · Governance and access control","category":"Governance and access control"},"category":"建立 AI 监管结构并确保监管合规","interaction":"read","references":[]},{"id":"3.2-lesson-2","title":"合规风险识别","body":"先确定业务用途、数据类型、适用地区与组织要求，再由相关责任人评估合规风险。通用清单不能代替具体判断。","example":"新用途涉及个人资料时，应先进行适用要求与授权核对。","skill":"3.2.2","quote":"确定并解决使用 AI 的业务流程的监管合规风险。","source":"用户提供的学习大纲 · 技能 3.2.2","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Compliance risk identification","body":"Determine intended use, data types, jurisdictions and applicable organizational requirements before evaluating compliance risks.","example":"Consult the responsible specialists before reusing personal information.","quote":"Learning objective 3.2.2 · Governance and access control","category":"Governance and access control"},"category":"建立 AI 监管结构并确保监管合规","interaction":"read","references":[]},{"id":"3.2-lesson-3","title":"访问控制与数据安全","body":"只授予完成工作所需的访问与操作权限，并在资料和工具层执行控制。仅靠提示词不能可靠替代权限系统。","example":"无权读取人事档案的员工，不应通过检索助手得到档案内容。","skill":"3.2.3","quote":"针对 AI 系统，确定合适的访问控制和数据安全措施。","source":"用户提供的学习大纲 · 技能 3.2.3","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Access control and data security","body":"Grant only necessary permissions and enforce them in data and tool systems; prompts alone cannot implement reliable access control.","example":"A retrieval assistant must not expose personnel files to unauthorized users.","quote":"Learning objective 3.2.3 · Governance and access control","category":"Governance and access control"},"category":"建立 AI 监管结构并确保监管合规","interaction":"assemble","references":[]},{"id":"3.2-lesson-4","title":"AI风险分类","body":"结合用途、受影响对象、潜在损害和控制条件分类风险，再安排评估与治理优先级；不要仅按模型大小分类。","example":"内部草稿辅助与影响个人重要权益的自动决定，需要不同控制。","skill":"3.2.4","quote":"应用 AI 风险分类框架，确立 AI 生命周期中监管和合规性决策的优先顺序。","source":"用户提供的学习大纲 · 技能 3.2.4","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"AI risk classification","body":"Classify a use case by potential impact, affected parties and controls to prioritize oversight.","example":"An internal drafting aid and a consequential automated decision need different controls.","quote":"Learning objective 3.2.4 · Governance and access control","category":"Governance and access control"},"category":"建立 AI 监管结构并确保监管合规","interaction":"read","references":[]}],"english":"Governance and access control","matchRequired":true},{"id":"3.3","title":"确定企业人工智能风险以及制定缓解策略","lessons":[{"id":"3.3-lesson-1","title":"生产监控与事件处理","body":"为运行质量、日志、异常处理、人工升级和回退设定机制。控制要在上线后持续发挥作用。","example":"错误率突然升高时限制受影响用途，再调查原因。","skill":"3.3.1","quote":"确定生产环境中 AI 系统的风险控制和监控机制需求。","source":"用户提供的学习大纲 · 技能 3.3.1","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Production monitoring and incidents","body":"Operate logging, quality checks, escalation, fallback and incident response throughout deployment.","example":"Restrict an affected use when error rates rise, then investigate.","quote":"Learning objective 3.3.1 · Risk management","category":"Risk management"},"category":"确定企业人工智能风险以及制定缓解策略","interaction":"read","references":[]},{"id":"3.3-lesson-2","title":"生命周期中的偏差","body":"偏差可能来自采样、标注、训练目标和部署环境等阶段。持续观察分组表现及环境变化，不把一次检查当作永久结论。","example":"整体分数稳定时，某一群体的错误仍可能增加。","skill":"3.3.2","quote":"了解在 AI 生命周期的多个阶段中可能会出现偏差，并说明持续监控偏差偏移的重要性。","source":"用户提供的学习大纲 · 技能 3.3.2","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Bias across the lifecycle","body":"Sampling, labeling, objectives and deployment context can introduce bias; evaluate relevant subgroup outcomes over time.","example":"A stable average score may hide worsening performance for one group.","quote":"Learning objective 3.3.2 · Risk management","category":"Risk management"},"category":"确定企业人工智能风险以及制定缓解策略","interaction":"read","references":[]},{"id":"3.3-lesson-3","title":"有害内容与知识产权","body":"检查内容风险、资料使用授权和输出用途，设置适当审核与处置流程。不假定模型生成就天然无害或无权利限制。","example":"公开发布生成内容前，根据用途检查来源与使用条件。","skill":"3.3.3","quote":"管理 AI 系统的有害内容风险和知识产权 (IP) 问题。","source":"用户提供的学习大纲 · 技能 3.3.3","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Harmful content and intellectual property","body":"Review content risks, input permissions and intended output uses; define review and remediation processes.","example":"Check publication rights and content suitability before releasing generated material.","quote":"Learning objective 3.3.3 · Risk management","category":"Risk management"},"category":"确定企业人工智能风险以及制定缓解策略","interaction":"assemble","references":[]},{"id":"3.3-lesson-4","title":"幻觉与可靠性","body":"幻觉可能表现为看似可信但无依据的内容。结合来源核验、数据质量检查、监测和必要人工复核来管理风险。","example":"带引用的回答仍需核对引用是否真正支持结论。","skill":"3.3.4","quote":"确定并减轻与 AI 系统可靠性相关的风险（例如，幻觉、数据质量下降、模型漂移）。","source":"用户提供的学习大纲 · 技能 3.3.4","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Hallucination and reliability","body":"A hallucination is plausible but unsupported or incorrect generated content; manage reliability through evidence, evaluation and appropriate review.","example":"Check whether a citation actually supports the claim.","quote":"Learning objective 3.3.4 · Risk management","category":"Risk management"},"category":"确定企业人工智能风险以及制定缓解策略","interaction":"read","references":[]}],"english":"Risk management","matchRequired":true}]},{"id":"4","title":"业务准备、领导力和 AI 转型","english":"Business Readiness, Leadership, and AI Transformation","zone":"observatory","sections":[{"id":"4.1","title":"评估 AI 业务的准备情况和成熟度","lessons":[{"id":"4.1-lesson-1","title":"组织准备度","body":"评估领导共识、数据、文化、基础设施与治理等维度；不能只检查是否买到了模型。","example":"演示效果好，但没有数据负责人和运营人员，仍不足以规模部署。","skill":"4.1.1","quote":"根据各关键维度（例如，领导层共识、数据质量、文化适应性、技术基础设施、监管框架），评估企业在采用 AI 方面的准备情况。","source":"用户提供的学习大纲 · 技能 4.1.1","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Organizational readiness","body":"Assess leadership alignment, data, culture, infrastructure and governance required to adopt and sustain AI.","example":"A successful demo is insufficient without data owners and operating support.","quote":"Learning objective 4.1.1 · Organizational readiness","category":"Organizational readiness"},"category":"评估 AI 业务的准备情况和成熟度","interaction":"read","references":[]},{"id":"4.1-lesson-2","title":"AI成熟度","body":"成熟度描述从探索、实验到可持续运营等能力状态。它用于识别下一步发展方向，不只是给组织打一个漂亮分数。","example":"能运行一次试点与能持续监测和维护多个应用，是不同能力。","skill":"4.1.2","quote":"运用 AI 成熟度模型，评估企业在 AI 旅程中所处的阶段（例如实验阶段、企业规模部署阶段）。","source":"用户提供的学习大纲 · 技能 4.1.2","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"AI maturity","body":"The stage of organizational capability, from exploration through experiments to repeatable operation at scale.","example":"Running one pilot differs from maintaining several monitored services.","quote":"Learning objective 4.1.2 · Organizational readiness","category":"Organizational readiness"},"category":"评估 AI 业务的准备情况和成熟度","interaction":"read","references":[]},{"id":"4.1-lesson-3","title":"能力差距","body":"从人员、流程、技术和治理找出具体缺口，区分缺少技能、缺少权限和缺少合适流程等问题。","example":"员工不会核验答案，不能只通过更换模型来解决。","skill":"4.1.3","quote":"确定在人员、流程、技术和监管等方面阻碍 AI 成功转型的具体能力差距。","source":"用户提供的学习大纲 · 技能 4.1.3","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Capability gaps","body":"Identify specific shortfalls in people, processes, technology and governance that prevent intended outcomes.","example":"Replacing a model does not teach employees how to verify its answers.","quote":"Learning objective 4.1.3 · Organizational readiness","category":"Organizational readiness"},"category":"评估 AI 业务的准备情况和成熟度","interaction":"assemble","references":[]},{"id":"4.1-lesson-4","title":"发展路线与投入顺序","body":"把能力建设与战略目标连接，依据当前准备程度安排可验证的阶段目标和投入。","example":"先建立数据责任和验证机制，再扩大相关业务用途。","skill":"4.1.4","quote":"确定开发投资的优先顺序，并根据战略目标和当前业务成熟度水平制定发展路线。","source":"用户提供的学习大纲 · 技能 4.1.4","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Roadmaps and investment sequencing","body":"Connect capability building to strategic goals and current readiness through evidence-based milestones.","example":"Establish data ownership and evaluation before expanding the use case.","quote":"Learning objective 4.1.4 · Organizational readiness","category":"Organizational readiness"},"category":"评估 AI 业务的准备情况和成熟度","interaction":"assemble","references":[]}],"english":"Organizational readiness","matchRequired":true},{"id":"4.2","title":"为 AI 建立数据基础和基础设施基础","lessons":[{"id":"4.2-lesson-1","title":"数据准备与孤岛","body":"检查资料质量、可访问性和共享障碍。分散资料是否能适当地用于当前用途，比单纯的数据总量更重要。","example":"多个部门各有不同版本的客户字段，需要先统一口径与权限。","skill":"4.2.1","quote":"评估数据准备情况（包括数据质量、可访问性），以及数据孤岛对 AI 计划的影响。","source":"用户提供的学习大纲 · 技能 4.2.1","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Data readiness and silos","body":"Assess quality, accessibility and appropriate sharing; disconnected data sources can obstruct consistent use.","example":"Reconcile different customer-field definitions across departments.","quote":"Learning objective 4.2.1 · Data and infrastructure","category":"Data and infrastructure"},"category":"为 AI 建立数据基础和基础设施基础","interaction":"read","references":[]},{"id":"4.2-lesson-2","title":"数据策略与所有权","body":"明确数据用途、责任人、质量维护和共享规则。数据能够共享不等于应对所有人开放。","example":"为制度资料指定更新责任人，并保留版本和使用范围。","skill":"4.2.2","quote":"描述为 AI 奠定基础的数据策略、数据所有权和数据共享框架的重要性。","source":"用户提供的学习大纲 · 技能 4.2.2","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Data strategy and ownership","body":"Assign intended uses, accountable owners, quality maintenance and sharing rules.","example":"Name an owner for policy updates and retain versions and access limits.","quote":"Learning objective 4.2.2 · Data and infrastructure","category":"Data and infrastructure"},"category":"为 AI 建立数据基础和基础设施基础","interaction":"read","references":[]},{"id":"4.2-lesson-3","title":"基础设施要求","body":"按工作负载评估计算、存储、网络、集成、监测和安全需求，并考虑运维与成本；不只比较硬件性能。","example":"交互式客服系统还要考虑延迟、可用性和失败时的处理方式。","skill":"4.2.3","quote":"评估支持 AI 计划的基础技术和基础设施要求。","source":"用户提供的学习大纲 · 技能 4.2.3","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Infrastructure requirements","body":"Assess compute, storage, networks, integration, monitoring, security and operations against workload needs and cost.","example":"An interactive service also needs acceptable latency and fallback behavior.","quote":"Learning objective 4.2.3 · Data and infrastructure","category":"Data and infrastructure"},"category":"为 AI 建立数据基础和基础设施基础","interaction":"assemble","references":[]}],"english":"Data and infrastructure","matchRequired":true},{"id":"4.3","title":"领导企业范围的变革，打造具备 AI 能力的员工队伍","lessons":[{"id":"4.3-lesson-1","title":"高管支持与AI倡导者","body":"领导层统一目标、提供资源并明确责任；倡导者推动沟通与实践，而不是替代正式治理。","example":"由业务负责人解释试点目标，并支持员工反馈问题。","skill":"4.3.1","quote":"建立高管层支持和领导层共识，识别并赋能 AI 倡导者，在整个企业中保持发展动力。","source":"用户提供的学习大纲 · 技能 4.3.1","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Executive support and AI champions","body":"Leaders align goals, resources and accountability; champions support communication and practice within governance.","example":"A business sponsor explains pilot goals and invites employee feedback.","quote":"Learning objective 4.3.1 · People and change","category":"People and change"},"category":"领导企业范围的变革，打造具备 AI 能力的员工队伍","interaction":"read","references":[]},{"id":"4.3-lesson-2","title":"跨职能团队","body":"把业务、技术、法律与合规等能力放进协作机制，明确交付、评估和异常处理的责任。","example":"试点负责人应知道谁可以决定暂停高风险功能。","skill":"4.3.2","quote":"组建涵盖不同专业领域（例如业务负责人、技术专家、法律、合规性等）的跨职能团队，并为 AI 计划制定明确的责任标准。","source":"用户提供的学习大纲 · 技能 4.3.2","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Cross-functional teams","body":"Combine business, technical and oversight capabilities with clear delivery and incident responsibilities.","example":"Know who can pause a risky feature during a pilot.","quote":"Learning objective 4.3.2 · People and change","category":"People and change"},"category":"领导企业范围的变革，打造具备 AI 能力的员工队伍","interaction":"read","references":[]},{"id":"4.3-lesson-3","title":"透明沟通","body":"说明实施时间、预期结果、岗位影响和支持安排；承认不确定性，提供双向反馈渠道。","example":"员工担心岗位变化时，不能只发布“必须使用”的通知。","skill":"4.3.3","quote":"制定透明的沟通策略，解决员工对 AI 的担忧（例如，实施时间表、预期结果、对员工角色的影响）。","source":"用户提供的学习大纲 · 技能 4.3.3","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Transparent communication","body":"Explain timing, expected outcomes, role impacts, support and uncertainties; enable two-way feedback.","example":"Address employees' job concerns rather than only mandating tool use.","quote":"Learning objective 4.3.3 · People and change","category":"People and change"},"category":"领导企业范围的变革，打造具备 AI 能力的员工队伍","interaction":"assemble","references":[]},{"id":"4.3-lesson-4","title":"文化障碍","body":"区分风险规避、抵触改变和害怕失败等原因，用反馈、安全试验和合适支持来回应。","example":"低使用率可能是信任与任务适配问题，而不只是安装不足。","skill":"4.3.4","quote":"认识 AI 采用中的文化障碍（例如，规避风险、抗拒改变、害怕失败），并确定领导层用来应对这些问题的干预措施。","source":"用户提供的学习大纲 · 技能 4.3.4","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Cultural barriers","body":"Distinguish risk aversion, resistance to change and fear of failure; respond with feedback, safe experimentation and support.","example":"Low adoption may reflect poor task fit or trust problems.","quote":"Learning objective 4.3.4 · People and change","category":"People and change"},"category":"领导企业范围的变革，打造具备 AI 能力的员工队伍","interaction":"read","references":[]},{"id":"4.3-lesson-5","title":"员工培养","body":"围绕岗位任务、实际风险和人机协作设计练习，可结合POC、培训或黑客马拉松；签到不代表形成能力。","example":"让客服练习核对引用、纠正草稿并识别需要上报的情况。","skill":"4.3.5","quote":"确定合适的员工培养方法，来加速提升整个企业的 AI 素养（例如，概念验证 [POC] 计划、黑客马拉松、培训计划、负责任的 AI 培训）。","source":"用户提供的学习大纲 · 技能 4.3.5","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Workforce development","body":"Build role-specific AI literacy through practical tasks, training, proofs of concept and responsible use exercises.","example":"Practice verifying citations and escalating uncertain answers.","quote":"Learning objective 4.3.5 · People and change","category":"People and change"},"category":"领导企业范围的变革，打造具备 AI 能力的员工队伍","interaction":"read","references":[]},{"id":"4.3-lesson-6","title":"角色转变与人的优势","body":"重新设计人工操作、人工监督和AI协作的分工，保留批判性思考、同理心与创造力的作用。","example":"AI起草沟通内容，人类判断对方处境并承担发送责任。","skill":"4.3.6","quote":"发现各种机会来转变人员的角色，从人工操作转向人工监督并与 AI 系统进行协作，以及制定战略决策，在人工优势（例如批判性思维、同理心、创造力）与 AI 功能之间取得平衡。","source":"用户提供的学习大纲 · 技能 4.3.6","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Changing roles and human strengths","body":"Redesign manual work, oversight and AI collaboration while preserving human judgment, empathy and creativity.","example":"AI drafts a message; a person assesses its context and authorizes sending.","quote":"Learning objective 4.3.6 · People and change","category":"People and change"},"category":"领导企业范围的变革，打造具备 AI 能力的员工队伍","interaction":"read","references":[]}],"english":"People and change","matchRequired":true},{"id":"4.4","title":"将 AI 从试点项目扩展到全企业部署","lessons":[{"id":"4.4-lesson-1","title":"迭代式转型","body":"按构想、实验、启动和扩展等阶段逐步验证。阶段之间应有反馈与决策依据，而非一次性替换全部流程。","example":"从小范围验证开始，观察结果后决定是否继续。","skill":"4.4.1","quote":"采用分阶段进行的迭代式转型方法（例如，构想、实验、启动、扩展）。","source":"用户提供的学习大纲 · 技能 4.4.1","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Iterative transformation","body":"Progress through ideation, experimentation, launch and scaling with feedback and decision gates.","example":"Start with a small test and use its results to decide the next step.","quote":"Learning objective 4.4.1 · From pilots to enterprise scale","category":"From pilots to enterprise scale"},"category":"将 AI 从试点项目扩展到全企业部署","interaction":"read","references":[]},{"id":"4.4-lesson-2","title":"从短期成果到扩展","body":"先获得可核验的小范围成果，再确认数据、流程和支持条件能否迁移到其他团队。","example":"志愿者试点成功，不代表所有部门立刻适用。","skill":"4.4.2","quote":"实施扩展方法，从短期成果开始，再逐步扩大到全企业部署。","source":"用户提供的学习大纲 · 技能 4.4.2","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"From quick wins to scale","body":"Verify an initial result, then test whether data, workflows and support transfer to additional teams.","example":"Volunteer pilot success does not establish suitability for every department.","quote":"Learning objective 4.4.2 · From pilots to enterprise scale","category":"From pilots to enterprise scale"},"category":"将 AI 从试点项目扩展到全企业部署","interaction":"read","references":[]},{"id":"4.4-lesson-3","title":"卓越中心 COE","body":"卓越中心可提供共享能力、标准、实践与协作支持。它不应让业务责任在集中支持中消失。","example":"把多个团队反复解决的问题整理成可复用的方法和支持机制。","skill":"4.4.3","quote":"建立 AI 卓越中心 (COE) 和跨职能协作机制来支持扩展。","source":"用户提供的学习大纲 · 技能 4.4.3","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Center of excellence (CoE)","body":"A shared capability that supports standards, reusable practices and cross-functional collaboration without removing business accountability.","example":"Reuse validated evaluation methods across several teams.","quote":"Learning objective 4.4.3 · From pilots to enterprise scale","category":"From pilots to enterprise scale"},"category":"将 AI 从试点项目扩展到全企业部署","interaction":"assemble","references":[]},{"id":"4.4-lesson-4","title":"持续反馈与价值跟踪","body":"同时跟踪使用、质量、风险、成本和长期业务价值，用反馈修正下一轮计划。","example":"账号开通数可以是活动指标，但不能单独证明业务价值。","skill":"4.4.4","quote":"建立持续的反馈机制和成功指标，用于跟踪 AI 计划的进展和长期价值。","source":"用户提供的学习大纲 · 技能 4.4.4","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Continuous feedback and value tracking","body":"Monitor use, quality, risks, costs and longer-term outcomes to adapt the transformation plan.","example":"Account creation alone does not demonstrate business value.","quote":"Learning objective 4.4.4 · From pilots to enterprise scale","category":"From pilots to enterprise scale"},"category":"将 AI 从试点项目扩展到全企业部署","interaction":"read","references":[]},{"id":"4.4-lesson-5","title":"试点转生产","body":"从实验到生产需要明确责任、运维、治理、支持和异常处置，而不是仅把演示页面公开。","example":"上线前确认谁值守、怎样监控、出错如何回退。","skill":"4.4.5","quote":"处理 AI 计划从实验阶段转向生产阶段的过渡，包括监管和运营要求。","source":"用户提供的学习大纲 · 技能 4.4.5","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Pilot-to-production transition","body":"Establish ownership, operations, governance, support and incident procedures before operating beyond an experiment.","example":"Confirm monitoring, on-call responsibility and rollback before launch.","quote":"Learning objective 4.4.5 · From pilots to enterprise scale","category":"From pilots to enterprise scale"},"category":"将 AI 从试点项目扩展到全企业部署","interaction":"read","references":[]},{"id":"4.4-lesson-6","title":"全企业推广","body":"评估跨团队数据差异、性能、连续性、培训和支持能力，以可控节奏推广并保留纠正空间。","example":"扩展过程中发现新部门资料不足时，可暂停该用途并补齐条件。","skill":"4.4.6","quote":"评估整个 AI 扩展计划在全企业推广中的多方面因素，确保业务连续性和性能。","source":"用户提供的学习大纲 · 技能 4.4.6","provenance":"依据大纲编写的教学解释与例子；不是大纲原文定义","en":{"title":"Enterprise rollout","body":"Assess differences in data, performance, continuity, training and support as adoption expands in controlled stages.","example":"Pause an unsuitable departmental rollout until missing conditions are addressed.","quote":"Learning objective 4.4.6 · From pilots to enterprise scale","category":"From pilots to enterprise scale"},"category":"将 AI 从试点项目扩展到全企业部署","interaction":"read","references":[]}],"english":"From pilots to enterprise scale","matchRequired":true}]}]};
if(typeof module!=="undefined")module.exports=StrategistCourse;
